head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDSTF10960.xml'; //공동공시 조회

scwin.gLdMktTp = js_market;
scwin.gubun = 0; //어느화면에서 수정했는지 체크.
scwin.filter_cnt = 0; //filter된 법인목록

scwin.arrMKT = [9, 1, 2, 6];
scwin.arrFORM = [1, 2, 3, 4];
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 현재날짜 셋팅	
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));
};
scwin.fn_Init = function() {
    checkbox_MKT0.setValue(1);
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        eval("checkbox_MKT" + scwin.arrMKT[i]).setValue(1);
    }
    panel_MKT1.style.visibility = "";
    panel_MKT2.style.visibility = "";
    panel_MKT6.style.visibility = "";
};
scwin.fn_getCheckedMKT = function() {
    var text = "";
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        if (eval("checkbox_MKT" + scwin.arrMKT[i]).checked) {
            text.setValue(text.getValue() + scwin.arrMKT[i] + ",");
        }
    }
    return text;
};
scwin.fn_getCheckedFORM = function() {
    var text = "";
    for (var i = 0; i < scwin.arrFORM.length; i++) {
        if (eval("checkbox_FORM" + scwin.arrFORM[i]).checked) {
            text.setValue(text.getValue() + scwin.arrFORM[i] + ",");
        }
    }
    return text;
};
scwin.fn_validCheck = function() {
    var a = 0;
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        if (eval("checkbox_MKT" + scwin.arrMKT[i]).checked) {
            a++;
        }
    }
    if (a == 0) {
        $c.win.alert("시장구분을 선택해 주세요.");
        checkbox_MKT0.focus();
        return false;
    }
    return true;
};
scwin.fn_Search = function() {
    if (!scwin.fn_validCheck()) return;
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    var url = "/MktActNotice.do?method=listJntDisclsMng" + "&ACPT_DATE=" + $c.stf.getObjectValue(edt_SrchDay) + "&LD_MKT_TP=" + scwin.fn_getCheckedMKT() + "&FORM_PROCS_CD=" + scwin.fn_getCheckedFORM() + "&FORM_KOR_NM=" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DisclsForm.DataID = encodeURI(url);
    dts_DisclsForm.reset();
    $c.cm.ShowWin(grd_DisclsForm);
};
scwin.fn_checkbox_FORM = function(flag) {
    if (flag == "0") {
        //전체
        if (checkbox_FORM0.checked) {
            for (var i = 0; i < scwin.arrFORM.length; i++) {
                eval("checkbox_FORM" + scwin.arrFORM[i]).setValue(1);
            }
        } else {
            for (var i = 0; i < scwin.arrFORM.length; i++) {
                eval("checkbox_FORM" + scwin.arrFORM[i]).setValue(0);
            }
        }
    } else {
        var a = 0;
        for (var i = 0; i < scwin.arrFORM.length; i++) {
            if (!eval("checkbox_FORM" + scwin.arrFORM[i]).checked) {
                a++;
            }
        }
        if (a == 0) {
            checkbox_FORM0.setValue(1);
        } else {
            checkbox_FORM0.setValue(0);
        }
    }
};
scwin.fn_checkbox_MKT = function(flag) {
    if (flag == "0") {
        //전체
        if (checkbox_MKT0.checked) {
            for (var i = 0; i < scwin.arrMKT.length; i++) {
                eval("checkbox_MKT" + scwin.arrMKT[i]).setValue(1);
            }
        } else {
            for (var i = 0; i < scwin.arrMKT.length; i++) {
                eval("checkbox_MKT" + scwin.arrMKT[i]).setValue(0);
            }
        }
    } else {
        var a = 0;
        for (var i = 0; i < scwin.arrMKT.length; i++) {
            if (!eval("checkbox_MKT" + scwin.arrMKT[i]).checked) {
                a++;
            }
        }
        if (a == 0) {
            checkbox_MKT0.setValue(1);
        } else {
            checkbox_MKT0.setValue(0);
        }
    }
};
scwin.dts_DisclsForm_OnLoadError = function() {
    $c.stf.alert_error(dts_DisclsForm);
    $c.cm.CloseWin('', grd_DisclsForm);
};
scwin.dts_DisclsForm_OnLoadCompleted = function(rowcount) {
    if (dts_DisclsForm.errorMsg) {
        $c.win.alert(dts_DisclsForm.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
    $c.cm.CloseWin(rowcount, grd_DisclsForm);
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    scwin.fn_Init();

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_Search();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var file_name = "공동공시조회";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_DisclsForm, file_name, xls_path, "8", 0);
    //grd_DisclsForm.GridToExcel("공동공시조회", "", "8");

};
scwin.checkbox_FORM0_onclick = function() {
    scwin.fn_checkbox_FORM(0);
};
scwin.checkbox_FORM1_onclick = function() {
    scwin.fn_checkbox_FORM(1);
};
scwin.checkbox_FORM2_onclick = function() {
    scwin.fn_checkbox_FORM(2);
};
scwin.checkbox_FORM4_onclick = function() {
    scwin.fn_checkbox_FORM(4);
};
scwin.checkbox_FORM3_onclick = function() {
    scwin.fn_checkbox_FORM(3);
};
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};
scwin.checkbox_MKT0_onclick = function() {
    scwin.fn_checkbox_MKT(0);
};
scwin.checkbox_MKT9_onclick = function() {
    scwin.fn_checkbox_MKT(9);
};
scwin.checkbox_MKT1_onclick = function() {
    scwin.fn_checkbox_MKT(1);
};
scwin.checkbox_MKT2_onclick = function() {
    scwin.fn_checkbox_MKT(2);
};
scwin.checkbox_MKT6_onclick = function() {
    scwin.fn_checkbox_MKT(6);
};
